"""Category-specific vocabularies admitted by the 2026-10-12 catalog audit.

Each row is an explicit mention rule, not a product specification or a claim
that an unmentioned feature is absent. Shared scoring/evidence code stays in
ope_product_report. No runtime model calls or cross-family fallback profiles.
"""
from __future__ import annotations


def rows(text: str) -> tuple[tuple[str, str, str], ...]:
    return tuple(tuple(line.split("|", 2)) for line in text.strip().splitlines())


def spec(code: str, name: str, tasks: str, materials: str, workflows: str, aspects: str) -> dict:
    return {"category_id": code, "display_name": name, "profile_id": code.replace("_", "-") + "/1.0.0",
            "category_label_en": name, "hero_title": f"从真实使用评论理解 {name} 的任务、体验与改进机会",
            "tasks": rows(tasks), "materials": rows(materials), "workflows": rows(workflows), "aspects": rows(aspects)}


